 1→import { spawn } from "node:child_process";
 2→import { logger } from "../utils/logger.js";
 3→
 4→export interface SpawnOptions {
 5→	command: string;
 6→	args: string[];
 7→	timeout?: number;
 8→	cwd?: string;
 9→	env?: Record<string, string | undefined>;
10→	stdin?: string;
11→}
12→
13→export interface SpawnResult {
14→	stdout: string;
15→	stderr: string;
16→	exitCode: number;
17→	durationMs: number;
18→	timedOut: boolean;
19→}
20→
21→const DEFAULT_TIMEOUT = 120_000; // 2 minutes
22→
23→export async function spawnAgent(options: SpawnOptions): Promise<SpawnResult> {
24→	const { command, args, timeout = DEFAULT_TIMEOUT, cwd, env, stdin } = options;
25→
26→	const controller = new AbortController();
27→	const startTime = Date.now();
28→
29→	logger.debug(`Spawning: ${command} ${args.join(" ")}`);
30→
31→	return new Promise<SpawnResult>((resolve) => {
32→		const child = spawn(command, args, {
33→			cwd,
34→			env: env ? { ...process.env, ...env } : process.env,
35→			signal: controller.signal,
36→			stdio: ["pipe", "pipe", "pipe"],
37→		});
38→
39→		const stdoutChunks: Buffer[] = [];
40→		const stderrChunks: Buffer[] = [];
41→		let timedOut = false;
42→
43→		const timer = setTimeout(() => {
44→			timedOut = true;
45→			controller.abort();
46→		}, timeout);
47→
48→		child.stdout?.on("data", (chunk: Buffer) => stdoutChunks.push(chunk));
49→		child.stderr?.on("data", (chunk: Buffer) => stderrChunks.push(chunk));
50→
51→		if (stdin) {
52→			child.stdin?.write(stdin);
53→			child.stdin?.end();
54→		} else {
55→			child.stdin?.end();
56→		}
57→
58→		child.on("close", (code) => {
59→			clearTimeout(timer);
60→			const durationMs = Date.now() - startTime;
61→			const stdout = Buffer.concat(stdoutChunks).toString("utf-8");
62→			const stderr = Buffer.concat(stderrChunks).toString("utf-8");
63→
64→			logger.debug(`Process exited: code=${code}, duration=${durationMs}ms`);
65→
66→			resolve({
67→				stdout,
68→				stderr,
69→				exitCode: code ?? 1,
