import { spawn } from "node:child_process";
import { logger } from "../utils/logger.js";

export interface SpawnOptions {
	command: string;
	args: string[];
	timeout?: number;
	cwd?: string;
	env?: Record<string, string | undefined>;
	stdin?: string;
}

export interface SpawnResult {
	stdout: string;
	stderr: string;
	exitCode: number;
	durationMs: number;
	timedOut: boolean;
}

const DEFAULT_TIMEOUT = 120_000; // 2 minutes

export async function spawnAgent(options: SpawnOptions): Promise<SpawnResult> {
	const { command, args, timeout = DEFAULT_TIMEOUT, cwd, env, stdin } = options;

	const controller = new AbortController();
	const startTime = Date.now();

	logger.debug(`Spawning: ${command} ${args.join(" ")}`);

	return new Promise<SpawnResult>((resolve) => {
		const child = spawn(command, args, {
			cwd,
			env: env ? { ...process.env, ...env } : process.env,
			signal: controller.signal,
			stdio: ["pipe", "pipe", "pipe"],
		});

		const stdoutChunks: Buffer[] = [];
		const stderrChunks: Buffer[] = [];
		let timedOut = false;

		const timer = setTimeout(() => {
			timedOut = true;
			controller.abort();
		}, timeout);

		child.stdout?.on("data", (chunk: Buffer) => stdoutChunks.push(chunk));
		child.stderr?.on("data", (chunk: Buffer) => stderrChunks.push(chunk));

		if (stdin) {
			child.stdin?.write(stdin);
			child.stdin?.end();
		} else {
			child.stdin?.end();
		}

		child.on("close", (code) => {
			clearTimeout(timer);
			const durationMs = Date.now() - startTime;
			const stdout = Buffer.concat(stdoutChunks).toString("utf-8");
			const stderr = Buffer.concat(stderrChunks).toString("utf-8");

			logger.debug(`Process exited: code=${code}, duration=${durationMs}ms`);

			resolve({
				stdout,
				stderr,
				exitCode: code ?? 1,
				durationMs,
				timedOut,
			});
		});

		child.on("error", (err) => {
			clearTimeout(timer);
			const durationMs = Date.now() - startTime;

			logger.error(`Process error: ${err.message}`);

			resolve({
				stdout: Buffer.concat(stdoutChunks).toString("utf-8"),
				stderr: err.message,
				exitCode: 1,
				durationMs,
				timedOut,
			});
		});
	});
}

