 1→import type { AgentResponse } from "../agents/types.js";
 2→import type { ParallelResult } from "./parallel.js";
 3→
 4→export function formatParallelResult(result: ParallelResult): string {
 5→	const sections: string[] = [];
 6→
 7→	sections.push(`## Multi-Agent Results (${result.totalDurationMs}ms total)\n`);
 8→
 9→	for (const response of result.responses) {
10→		const status = response.error ? "ERROR" : "OK";
11→		sections.push(
12→			`### ${response.agent} (${response.model}) [${status}] — ${response.durationMs}ms`,
13→		);
14→		sections.push(response.error ? `Error: ${response.error}` : response.content);
15→		sections.push("");
16→	}
17→
18→	if (result.errors.length > 0) {
19→		sections.push("### Errors");
20→		for (const err of result.errors) {
21→			sections.push(`- **${err.agent}**: ${err.error}`);
22→		}
23→		sections.push("");
24→	}
25→
26→	return sections.join("\n");
27→}
28→
29→export function formatComparisonResult(responses: AgentResponse[]): string {
30→	if (responses.length === 0) return "No responses received.";
31→	if (responses.length === 1) return formatSingleResponse(responses[0]);
32→
33→	const sections: string[] = [];
34→	sections.push("## Cross-Agent Comparison\n");
35→
36→	for (const response of responses) {
37→		sections.push(`### ${response.agent} (${response.model}) — ${response.durationMs}ms`);
38→		sections.push(response.content);
39→		sections.push("");
40→	}
41→
42→	sections.push("### Summary");
43→	sections.push(`- **Total agents**: ${responses.length}`);
44→	sections.push(
45→		`- **Fastest**: ${responses.reduce((a, b) => (a.durationMs < b.durationMs ? a : b)).agent}`,
46→	);
47→	sections.push(
48→		`- **Slowest**: ${responses.reduce((a, b) => (a.durationMs > b.durationMs ? a : b)).agent}`,
49→	);
50→
51→	return sections.join("\n");
52→}
53→
54→export function formatSingleResponse(response: AgentResponse): string {
55→	const header = `**${response.agent}** (${response.model}) — ${response.durationMs}ms`;
56→
57→	if (response.error) {
58→		return `${header}\n\nError: ${response.error}`;
59→	}
60→
61→	return `${header}\n\n${response.content}`;
62→}
63→
64→export function formatVerificationResult(
65→	agent: string,
66→	responses: AgentResponse[],
67→): string {
68→	const sections: string[] = [];
69→	sections.push(`## Cross-Model Verification (${agent})\n`);
70→
